/* SPDX-License-Identifier: GPL-3.0-only
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments */
/* Host test of firmware/src/ota.c: a fake M-UPGRADE serves a real .fwsc over
 * the SysEx protocol (pack7, cmd 0x30 reads, 0xE0000000 -> "success") and a
 * simulated NOR plays the flash.
 *   cc -o ota_test tests/ota_test.c && ./ota_test FILE.fwsc
 * With -DBOARD_SMK37=1 (an SMK-37 Pro package): staging 0xBB000, record 0xBFF00, parm ota-SMK-37 Pro_016.
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define FELUCCA_OTA_DRYRUN 0
#if BOARD_SMK37                          /* -DBOARD_SMK37=1: the SMK-37 Pro build of ota.c */
#if T_MODEL == 1                         /* -DT_MODEL=1 / 2: the MODEL=elite / mke build */
#define SMK_MODEL "SMK-37 Elite"
#elif T_MODEL == 2
#define SMK_MODEL "MKE-P37"
#else
#define SMK_MODEL "SMK-37 Pro"
#endif
#define FELUCCA_ID SMK_MODEL "_900"
#define T_AREA 0xBB000u
#define T_PARM_ID "ota-" SMK_MODEL "_016"
#else
#define FELUCCA_ID "FM-1_900"
#define T_AREA 0xE0000u
#define T_PARM_ID "ota-FM-1_015"
#endif
#define T_AREA_HI (T_AREA + 0x5000u)

static uint8_t nor[0x100000];
static uint8_t *logical;
static size_t logical_len;
static uint8_t rx[1024];                 /* one pending host frame (7-bit bytes) */
static uint32_t rx_len, rx_full;
static uint32_t now_ms, requests, ident_replies, mute_after = 0xFFFFFFFFu, bad_erase;
static int committed;
static uint8_t committed_parm[112];
static int32_t last_code;
static uint8_t *corrupt_at;              /* flip a served byte (loader body) */

static uint32_t pack7(const uint8_t *in, uint32_t n, uint8_t *out)
{
    uint32_t acc = 0, nb = 0, o = 0;
    while (n--) {
        acc |= (uint32_t)*in++ << nb;
        nb += 8;
        while (nb >= 7) { out[o++] = acc & 0x7F; acc >>= 7; nb -= 7; }
    }
    if (nb) out[o++] = acc & 0x7F;
    return o;
}

static uint32_t unpack7h(const uint8_t *in, uint32_t n, uint8_t *out)
{
    uint32_t acc = 0, nb = 0, o = 0;
    while (n--) {
        acc |= (uint32_t)*in++ << nb;
        nb += 7;
        if (nb >= 8) { out[o++] = (uint8_t)acc; acc >>= 8; nb -= 8; }
    }
    return o;
}

static void host_reply(const uint8_t *msg, uint32_t n)       /* queue msg as a device-bound frame */
{
    rx_len = pack7(msg, n, rx);
    rx_full = 1;
}

/* ---- hooks ---- */
static int ota_wire_send(const uint8_t *p, uint32_t n)
{
    uint8_t u[64], m[600];
    uint32_t d, addr, len, i, s = 0;
    if (p[0] != 0xF0 || p[n - 1] != 0xF7) { printf("bad wire framing\n"); exit(1); }
    d = unpack7h(p + 1, n - 2, u);
    if (u[2] == 0x11) { ident_replies++; return 0; }
    if (d != 15 || u[2] != 0x30) { printf("unexpected device msg cmd %02x len %u\n", u[2], d); exit(1); }
    addr = u[7] | u[8] << 8 | u[9] << 16 | (uint32_t)u[10] << 24;
    len = u[11] | u[12] << 8 | u[13] << 16;
    if (++requests > mute_after)
        return 0;                                         /* host gone */
    memcpy(m, "\x00\x59\x30", 3);
    m[3] = (uint8_t)(len + 8); m[4] = (uint8_t)((len + 8) >> 8); m[5] = 0;
    m[6] = 0;
    memcpy(m + 7, &addr, 4);
    m[11] = (uint8_t)len; m[12] = (uint8_t)(len >> 8); m[13] = 0;
    if (addr == 0xE0000000u) {
        memset(m + 14, 0, len);
        memcpy(m + 14, "success", 8);
    } else {
        if (addr + len > logical_len) { printf("read past the package %#x\n", addr); exit(1); }
        memcpy(m + 14, logical + addr, len);
        if (corrupt_at && corrupt_at >= logical + addr && corrupt_at < logical + addr + len)
            m[14 + (corrupt_at - (logical + addr))] ^= 0x01;
    }
    for (i = 6; i < 14 + len; i++) s += m[i];
    m[14 + len] = (uint8_t)~s;
    host_reply(m, 15 + len);
    return 0;
}
static int ota_frame_get(const uint8_t **p, uint32_t *n)
{
    if (!rx_full) return 0;
    *p = rx; *n = rx_len;
    return 1;
}
static void ota_frame_done(void) { rx_full = 0; }
static uint32_t ota_now_ms(void) { return now_ms; }
static void ota_idle(void) { now_ms += 1; }
static int ota_erase(uint32_t off)
{
    if (off < T_AREA || off >= T_AREA_HI || (off & 0xFFFu)) { bad_erase++; return -8; }
    memset(nor + off, 0xFF, 4096);
    return 0;
}
static int ota_prog(uint32_t off, const void *src, uint32_t n)
{
    const uint8_t *s = src;
    uint32_t i;
    if (off < T_AREA || off + n > T_AREA_HI) { bad_erase++; return -8; }
    for (i = 0; i < n; i++) nor[off + i] &= s[i];
    return 0;
}
static int ota_fread(uint32_t off, void *dst, uint32_t n) { memcpy(dst, nor + off, n); return 0; }
static void ota_show(uint32_t step, int32_t code) { if (step == 9) last_code = code; }
static void ota_commit(const uint8_t *parm) { committed = 1; memcpy(committed_parm, parm, 112); }

#include "../firmware/src/ota.c"

static uint32_t ota_body_off(void)                  /* ota.bin data + 0x20 in the logical image */
{
    uint8_t h[0x400];
    uint32_t i, n;
    memcpy(h, logical, sizeof h);
    ota_jl_enc(h, 0x40);
    n = ota_rd16(h + 8);
    for (i = 0; i < n; i++) {
        uint8_t *e = h + 0x40 + i * 0x50u;
        ota_jl_enc(e, 0x50);
        if (ota_rd16(e) == 100) return ota_rd32(e + 8) + 0x20u;
    }
    return 0;
}

static int check(const char *what, int ok)
{
    printf("%-52s %s\n", what, ok ? "ok" : "FAIL");
    return ok ? 0 : 1;
}

static int area_erased(void)
{
    uint32_t i;
    for (i = T_AREA; i < T_AREA_HI; i++) if (nor[i] != 0xFF) return 0;
    return 1;
}

static void reset_dev(void)
{
    memset(nor, 0xFF, sizeof nor);
    memcpy(nor, logical + 0x400, 0x4000);                 /* device flash head = package flash.bin head */
    rx_full = 0; requests = 0; ident_replies = 0; committed = 0; last_code = 0;
    mute_after = 0xFFFFFFFFu; corrupt_at = NULL; bad_erase = 0;
}

int main(int argc, char **argv)
{
    FILE *f;
    uint8_t *raw;
    size_t n, i;
    int bad = 0, rc;
    if (argc < 2) { printf("usage: ota_test FILE.fwsc\n"); return 2; }
    f = fopen(argv[1], "rb");
    if (!f) { perror(argv[1]); return 2; }
    raw = malloc(0x200000);
    n = fread(raw, 1, 0x200000, f);
    fclose(f);
    logical = malloc(n);
    for (i = 0; i < 20; i++) memcpy(logical + i * 47, raw + i * 48, 47);   /* drop the marker bytes */
    memcpy(logical + 20 * 47, raw + 20 * 48, n - 20 * 48);
    logical_len = n - 20;

    /* handshake outside a session */
    reset_dev();
    {
        uint8_t m[7] = {0, 0x59, 0x11, 0, 0, 0, 0xFF};
        host_reply(m, 7);
        ota_service();
        bad += check("handshake answered", ident_replies == 1);
        bad += check("identity frame is " FELUCCA_ID,
                     ota_msg[2] == 0x11 && !memcmp(ota_msg + 6, FELUCCA_ID, sizeof FELUCCA_ID - 1));
    }

    /* full session */
    reset_dev();
    rc = ota_session();
    printf("  %u requests\n", requests);
    bad += check("session commits", rc == 0 && committed);
    bad += check("headers + loader + confirm, no head reads", requests >= 10 && requests <= 30);
    {
        uint8_t *h = nor + T_AREA, *p = committed_parm;
        uint32_t k, zero = 1;
        for (k = 8u + sizeof T_PARM_ID - 1u; k < 0x28u; k++)
            zero &= p[k] == 0;
        bad += check("staged body == the package's loader", !memcmp(nor + T_AREA + 0x20u, logical + ota_body_off(), 64));
        bad += check("LOADER.BIN head CRC",
                     (h[0] | h[1] << 8) == ota_crc16(h + 2, 30, 0) && !memcmp(h + 16, "LOADER.BIN", 10));
        bad += check("record at the area end - 256 == RAM record", !memcmp(nor + T_AREA_HI - 0x100u, p, 112));
        bad += check("parm identity " T_PARM_ID ", zero to +0x27",
                     !memcmp(p + 8, T_PARM_ID, sizeof T_PARM_ID - 1u) && zero);
        bad += check("record CRC / type / magic / ota_addr",
                     (p[0] | p[1] << 8) == ota_crc16(p + 2, 78, 0) && (p[2] | p[3] << 8) == 0x5A0D &&
                     (p[6] | p[7] << 8) == 0x5441 && ota_rd32(p + 72) == T_AREA);
        bad += check("nothing written outside the staging area", bad_erase == 0);
    }
    /* boot cleanup erases it */
    bad += check("boot cleanup erases the area", ota_boot_cleanup() == 1 && area_erased());
    bad += check("second boot: nothing to do", ota_boot_cleanup() == 0);

    /* host disappears in the middle */
    reset_dev();
    mute_after = 4;
    rc = ota_session();
    bad += check("host gone -> no commit, area clean", rc < 0 && !committed && area_erased());

    /* host never confirms */
    reset_dev();
    mute_after = 0xFFFFFFFFu;
    {
        uint32_t total;
        rc = ota_session();
        total = requests;                                  /* requests of a full run incl. confirm */
        reset_dev();
        mute_after = total - 1;                            /* answer everything but the confirmation */
        rc = ota_session();
        bad += check("no 'success' -> -13, no commit, area clean", rc == -13 && !committed && area_erased());
    }

    printf("%s\n", bad ? "OTA TEST FAILED" : "ota test passed");
    return bad != 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Product Miami / WBL1 backend (also host tests). */
#pragma once
#include "wobble_config.h"
#if !X0X_WOBBLE && !defined(X0X_SYNTH_HOST_TEST)
#error "Wobble backend requires X0X_WOBBLE=1 or host synth tests"
#endif
#include "synth_engine.h"
#include "../../../experiments/wobble/wobble.h"
#define WOBBLE_EXPERIMENT_ENGINE 0x57424c31u /* WBL1; distinct from native303=1 */
#define WOBBLE_EXPERIMENT_SCHEMA 1u
static void wobble_foundation_init(void *p) { wobble_init(p, SYNTH_SAMPLE_RATE); }
static void wobble_foundation_render(void *p, float *out, int n)
{
    /* Bounded 16-frame mono compatibility scratch, not the stereo mixer path. */
    float right[16];
    if (n < 1 || n > (int)SYNTH_MAX_BLOCK) return;
    for (int pos = 0; pos < n; pos += 16) {
        int count = n - pos < 16 ? n - pos : 16;
        wobble_render(p, out + pos, right, (size_t)count);
        for (int i = 0; i < count; ++i) out[pos+i] = .5f * (out[pos+i] + right[i]);
    }
}
static void wobble_foundation_note(void *p, int note, int accent, int slide, int velocity)
{
    /* Held slides continue the amp envelope; W_GLIDE controls pitch slew. */
    (void)accent;
    if (note < 0) note = 0;
    if (note > 127) note = 127;
    if (velocity < 0) velocity = 0;
    if (velocity > 127) velocity = 127;
    wobble_note_on_slide(p, (uint8_t)note, (uint8_t)velocity, slide);
}
static void wobble_foundation_off(void *p) { wobble_all_notes_off(p); }
static void wobble_foundation_panic(void *p) { wobble_reset(p); }
static void wobble_foundation_set(void *p, int parameter, int value)
{
    if (parameter < 0 || parameter >= (int)WOBBLE_EXPERIMENT_NPARAMS) return;
    if (value < 0) value = 0;
    if (value > 127) value = 127;
    /* The Miami page stores switches as 0/1, while the DSP threshold is 0.5.
     * Sending 1/127 left Wave, XMod Wave, Wobble Shape and Damper permanently OFF. */
    float norm = (float)value / 127.0f;
    if (parameter == W_CARRIER_WAVE || parameter == W_XMOD_WAVE ||
        parameter == W_WOBBLE_SHAPE || parameter == W_DAMPER || parameter == W_WOBBLE_DIV)
        norm = value ? 1.0f : 0.0f;
    wobble_set(p, (unsigned)parameter, norm);
}
static void wobble_foundation_transport(void *p, int running) { (void)p; (void)running; }
static int wobble_foundation_active(const void *p) { return ((const wobble_t *)p)->gate; }
static int wobble_foundation_idle(const void *p) { return !((const wobble_t *)p)->active; }
/* No alternate lite-quality implementation is claimed. */
static void wobble_foundation_lite(void *p, int lite) { (void)p; (void)lite; }
static const synth_ops_t wobble_foundation_ops = {
    WOBBLE_EXPERIMENT_ENGINE, WOBBLE_EXPERIMENT_SCHEMA, WOBBLE_EXPERIMENT_NPARAMS,
    wobble_foundation_init, wobble_foundation_render, wobble_foundation_note,
    wobble_foundation_off, wobble_foundation_panic, wobble_foundation_set,
    wobble_foundation_transport, wobble_foundation_active, wobble_foundation_idle,
    wobble_foundation_lite
};
static inline synth_binding_t wobble_foundation_binding(wobble_t *context)
{ synth_binding_t b = { &wobble_foundation_ops, context }; return b; }

/* Distinct caller-owned buffers; preserves original side signal. */
static inline int wobble_backend_stereo(synth_slot_t *s, float *l, float *r, int n)
{
    if (!s || !l || !r || l == r || n < 1 || n > (int)SYNTH_MAX_BLOCK ||
        s->active.ops != &wobble_foundation_ops) return 0;
    wobble_render(s->active.context, l, r, (size_t)n); return 1;
}
/* Version1 retained bank is exactly sixteen 7-bit control bytes, no raw floats. */
static inline int wobble_bank_load(wobble_t *s, uint32_t id, unsigned schema,
                                   const uint8_t *bank, size_t n)
{
    if (!s || !bank || id != WOBBLE_EXPERIMENT_ENGINE || schema != 1 || n != 16) return 0;
    for (unsigned i=0; i<16; ++i) if (bank[i]>127) return 0;
    /* Version-1 banks retain their original 7-bit values. Live Miami switches
     * use 0/1 UI controls, but normalizing a legacy nonzero byte to 127 here
     * would change the bank on save and silently change its old DSP meaning. */
    for (unsigned i=0; i<16; ++i) wobble_set(s,i,(float)bank[i]/127.0f);
    wobble_set(s,W_WOBBLE_DIV,0); /* A legacy bank never carries the new override. */
    return 1;
}
/* Never silently discard an active division override into the old 16-byte bank.
 * Product projects use the separate tagged sound schema and retain the field. */
static inline int wobble_bank_save(const wobble_t *s, uint8_t bank[16])
{
    if (s->p[W_WOBBLE_DIV] >= 0.5f) return 0;
    for (unsigned i=0; i<16; ++i) bank[i]=(uint8_t)(s->p[i]*127.0f+.5f);
    return 1;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* External-clock dropout: a held 303 MIDI note must be released, and
 * a new input may resume on the next step without an early/doubled note.
 * Native test links the production sequencer, pattern and TB-3PO sources. */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "sequencer.h"

#define CHECK(e) do { checks++; if (!(e)) { failures++; if (failures < 25) \
    fprintf(stderr, "FAIL block=%u line=%d: %s\n", block, __LINE__, #e); } } while (0)
typedef struct {
    unsigned ons, offs, steps, clock_out, transport_out, duplicate, orphan;
    uint8_t held[16][128];
    int last_step;
} output_t;
static pattern_t patterns[NPAT];
static unsigned checks, failures, block;

static void midi_out(void *ctx, uint8_t st, uint8_t note, uint8_t vel)
{
    output_t *o = ctx;
    unsigned kind = st & 0xF0u, ch = st & 15u;
    if (st >= 0xF8u) {
        if (st == 0xF8u) o->clock_out++;
        else o->transport_out++;
    } else if (kind == 0x90u && vel) {
        if (o->held[ch][note]) o->duplicate++;
        o->held[ch][note] = 1;
        o->ons++;
    } else if (kind == 0x80u || (kind == 0x90u && !vel)) {
        if (!o->held[ch][note]) o->orphan++;
        o->held[ch][note] = 0;
        o->offs++;
    }
}
static void step_out(void *ctx, int part, int step)
{
    output_t *o = ctx;
    if (part == TRK_BASS0) {o->steps++; o->last_step = step;}
}
static int bass_on(void *ctx, int part, int note, int accent, int slide, int vel)
{ (void)ctx; (void)part; (void)note; (void)accent; (void)slide; (void)vel;  return 1; }
static void bass_off(void *ctx, int part) { (void)ctx; (void)part; }
static int drum(void *ctx, int kit, int voice, float vel)
{ (void)ctx; (void)kit; (void)voice; (void)vel; return 1; }

static void render(seq_t *s, const seq_sink_t *out, uint32_t n)
{
    while (n) {
        uint32_t k = seq_until_event(s, n);
        CHECK(k > 0 && k <= n);
        if (!k || k > n) return;
        seq_advance(s, k, out);
        n -= k;
    }
}
static void render_blocks(seq_t *s, const seq_sink_t *out, uint32_t frames)
{
    while (frames) {
        uint32_t n = frames < block ? frames : block;
        render(s, out, n);
        frames -= n;
    }
}
static int clock_packet(seq_t *s, const seq_sink_t *out, unsigned input)
{
    int accepted = seq_clk_take(s, 0xF8u, input);
    if (accepted) seq_midi_rt(s, 0xF8u);
    render(s, out, 1);
    return accepted;
}
static void check_note_state(const output_t *o, unsigned expected)
{
    unsigned held = 0;
    for (unsigned ch = 0; ch < 16u; ch++)
        for (unsigned note = 0; note < 128u; note++) held += o->held[ch][note];
    CHECK(held == expected);
}

int main(void)
{
    const uint32_t blocks[] = {1u, 64u, 1024u};
    for (unsigned i = 0; i < sizeof blocks / sizeof *blocks; i++) {
        block = blocks[i];
        for (unsigned p = 0; p < NPAT; p++) pattern_init(&patterns[p], p + 17u, p + 39u);
        for (unsigned p = 0; p < 16u; p++)
            patterns[0].bass[0].step[p] = (bstep_t){(uint8_t)(60u + (p % 3u)), G_NOTE | BS_SLIDE, 100};
        patterns[0].bass[0].len = 16;
        seq_t s;
        seq_init(&s, patterns);
        s.clk_src = SEQ_CLK_EXT;
        s.send_notes = 1;
        output_t o = {0};
        const seq_sink_t sink = {.ctx=&o, .midi=midi_out, .step=step_out,
                                 .bass_on=bass_on, .bass_off=bass_off, .drum=drum};
        render(&s, &sink, 1);                  /* select EXTERNAL */
        seq_start(&s);
        render(&s, &sink, 1);                  /* local PLAY arms, no clock */
        CHECK(s.playing && s.ext);
        CHECK(o.steps == 0 && o.ons == 0);
        CHECK(clock_packet(&s, &sink, 0) == 1); /* USB: first tick plays step 1 */
        CHECK(o.steps == 1 && o.ons == 1 && o.offs == 0);
        check_note_state(&o, 1);
        CHECK(clock_packet(&s, &sink, 1) == 0); /* Bluetooth cannot steal live USB lock */
        CHECK(o.steps == 1);

        render_blocks(&s, &sink, FS / 2u + 2u); /* no clock > 0.5 s */
        CHECK(seq_clock_waiting(&s));
        CHECK(s.playing && s.ext && s.clk_lost);
        CHECK(o.steps == 1);
        CHECK(o.ons == 1 && o.offs == 1);     /* timeout releases held slide */
        check_note_state(&o, 0);
        CHECK(s.clk_lock == 0);               /* timed-out owner relinquishes input */

        for (unsigned tick = 1; tick <= 5u; tick++) {
            CHECK(clock_packet(&s, &sink, 1) == 1); /* Bluetooth takes over */
            CHECK(o.steps == 1 && o.ons == 1); /* no phantom first step */
        }
        CHECK(!seq_clock_waiting(&s));
        CHECK(clock_packet(&s, &sink, 0) == 0); /* USB no longer owns */
        CHECK(clock_packet(&s, &sink, 1) == 1); /* sixth new tick: next step */
        CHECK(o.steps == 2 && o.ons == 2 && o.offs == 1);
        CHECK(o.last_step == 1);              /* zero-based step 2 */
        check_note_state(&o, 1);
        seq_stop(&s);
        render(&s, &sink, 1);
        seq_stop(&s);                         /* idempotent STOP and NoteOff */
        render(&s, &sink, 1);
        CHECK(!s.playing);
        CHECK(o.ons == 2 && o.offs == 2);
        CHECK(o.duplicate == 0 && o.orphan == 0);
        CHECK(o.transport_out == 0 && o.clock_out == 0); /* EXTERNAL echoes nothing */
        check_note_state(&o, 0);
    }
    fprintf(stderr, "seq external dropout/resume: %u/%u checks %s\n",
            checks - failures, checks, failures ? "FAILED" : "PASSED");
    return failures ? EXIT_FAILURE : EXIT_SUCCESS;
}

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""fm1_rescue: put stock firmware back on an FM-1 through the chip's own update mode (the
mask-ROM "UBOOT"), from a Mac, with no extra hardware.

For an FM-1 whose firmware crashes at start-up. X0X 0.2-beta crashes at once, and after two failed
boots enters UBOOT, which shows up on USB as "WL80UBOOT1.00" (4C4A:8057). macOS then takes it for a
disk, upsets it, and it reboots into the crash a few seconds later; this script waits for it,
takes it away from macOS (hence sudo) and keeps it.

  python3 -m venv ~/fm1-rescue && ~/fm1-rescue/bin/pip install pyusb libusb-package
  sudo ~/fm1-rescue/bin/python fm1_rescue.py FM-1.fwsc            # check and back up, write nothing
  sudo ~/fm1-rescue/bin/python fm1_rescue.py FM-1.fwsc --write    # then write stock

FM-1.fwsc is M-VAVE's FM-1 V15 (m-vave.com/download, PC Firmware); only that exact file is
accepted. The protocol and the write policy are FM-1-transporter's (github.com/kurogedelic/
FM-1-transporter, docs/PROTOCOL.md), which were verified on hardware:

  1. JieLi's flash loader (wl82loader.bin, from github.com/kagaimiq/jl-uboot-tool, downloaded
     and checked against its hash) is loaded into RAM and started;
  2. the chip key must be 980F and the flash 856014 (1 MiB), or nothing is done;
  3. the whole flash is read and saved as a backup before anything else;
  4. only 4 KiB sectors in [0x4000, 0x93000) that differ from V15 are written (the bootloader below
     0x4000 and the device data above 0x93000 are never touched; a difference below 0x4000 stops
     it), each erased, written and read back;
  5. a final full read must equal the expected image; then the FM-1 restarts into V15.
"""
import argparse
import hashlib
import os
import struct
import sys
import time
import urllib.request

VID, PID = 0x4C4A, 0x8057
STOCK_SHA256 = "db1642b2b6fa5c2cccb11ffd13878068bb28601678d3644049f99dc40e7edb8a"
LOADER_URL = ("https://raw.githubusercontent.com/kagaimiq/jl-uboot-tool/"
              "c32b28e7a04f873f526ba929cb1bae9f05442fe9/data/loaderblobs/usb/wl82loader.bin")
LOADER_SHA256 = "d41da6126760c9d66660bcc0cac8d27d221806c5e369a8036921efe68dca5376"
LOADER_ADDR, LOADER_ARG = 0x1C02000, 0x0001

FLASH_SIZE = 0x100000
APP_END = 0x93000          # the .fwsc flash entry is raw flash [0, APP_END)
WRITE_MIN = 0x4000         # flash header, SPL, isd_config: never written
SECTOR = 0x1000
IO = 512

# ROM UBOOT1.00
CMD_WRITE_MEMORY, CMD_READ_MEMORY, CMD_JUMP = 0xFB06, 0xFD07, 0xFB08
# loader
CMD_ERASE_SECTOR, CMD_WRITE_FLASH, CMD_READ_FLASH = 0xFB01, 0xFB04, 0xFD05
CMD_READ_KEY, CMD_GET_ONLINE_DEVICE, CMD_RUN_APP = 0xFC09, 0xFC0A, 0xFC0C


class Fail(Exception):
    pass


# ------------------------------------------------------------------ maths ---
def crc16(data, crc=0):
    """CRC-16/XMODEM (poly 0x1021, no reflection)"""
    for b in data:
        crc ^= b << 8
        for _ in range(8):
            crc = ((crc << 1) ^ 0x1021) & 0xFFFF if crc & 0x8000 else (crc << 1) & 0xFFFF
    return crc


MAGIC = bytes([0xC3, 0xCF, 0xC0, 0xE8, 0xCE, 0xD2, 0xB0, 0xAE,
               0xC4, 0xE3, 0xA3, 0xAC, 0xD3, 0xF1, 0xC1, 0xD6])


def crc_cipher(buf):
    """JieLi's CrcDecode cipher, key 0xFFFFFFFF (in place)"""
    crc = crc16(b"\xFF\xFF", 0xFFFF)
    for i in range(len(buf)):
        crc = crc16(MAGIC[i % 16:i % 16 + 1], crc)
        buf[i] ^= crc & 0xFF


def enc(buf, key=0xFFFF):
    """JieLi ENC stream cipher (in place)"""
    for i in range(len(buf)):
        buf[i] ^= key & 0xFF
        key = ((key << 1) ^ (0x1021 if key & 0x8000 else 0)) & 0xFFFF


# ---------------------------------------------------------------- package ---
def package_flash_image(raw):
    """The .fwsc's type-0 entry: raw flash [0, APP_END). Layout as tools/fm1pkg_make.py writes it:
    the logical image is the .fwsc without the marker byte after each of its first 20 0x2F-byte
    blocks; it starts with a 0x40-byte header and a list of 0x50-byte entries, each ENC'd."""
    logical = bytearray()
    for i in range(20):
        logical += raw[i * 0x30:i * 0x30 + 0x2F]
    logical += raw[20 * 0x30:]
    hdr = bytearray(logical[0:0x40])
    enc(hdr)
    n = struct.unpack_from("<H", hdr, 8)[0]
    if hdr[16:22] != b"AC791N" or not 0 < n < 16:
        raise Fail("not an FM-1 package (header)")
    for i in range(n):
        e = bytearray(logical[0x40 + i * 0x50:0x40 + (i + 1) * 0x50])
        enc(e)
        typ, _, dcrc, _, off, size = struct.unpack_from("<HHHHII", e, 0)
        if typ == 0:
            data = bytes(logical[off:off + size])
            if len(data) != size or crc16(data) != dcrc:
                raise Fail("package flash entry: bad CRC")
            return data
    raise Fail("package has no flash entry")


# -------------------------------------------------------------- transport ---
class Bot:
    """USB mass storage bulk-only transport: one SCSI-style command per call."""

    def __init__(self, dev, usb):
        self.dev, self.usb, self.tag = dev, usb, 1
        cfg = dev.get_active_configuration() if self._configured() else None
        if cfg is None:
            dev.set_configuration()
            cfg = dev.get_active_configuration()
        intf = cfg[(0, 0)]
        self.intf = intf.bInterfaceNumber
        util = usb.util
        self.ep_out = util.find_descriptor(intf, custom_match=lambda e: util.endpoint_direction(
            e.bEndpointAddress) == util.ENDPOINT_OUT and util.endpoint_type(e.bmAttributes) == util.ENDPOINT_TYPE_BULK)
        self.ep_in = util.find_descriptor(intf, custom_match=lambda e: util.endpoint_direction(
            e.bEndpointAddress) == util.ENDPOINT_IN and util.endpoint_type(e.bmAttributes) == util.ENDPOINT_TYPE_BULK)
        if self.ep_out is None or self.ep_in is None:
            raise Fail("no bulk endpoints")
        util.claim_interface(dev, self.intf)

    def _configured(self):
        try:
            self.dev.get_active_configuration()
            return True
        except self.usb.core.USBError:
            return False

    def reset_recovery(self):
        """Bulk-only mass storage reset, then clear both halts (what a host does after a stall)."""
        try:
            self.dev.ctrl_transfer(0x21, 0xFF, 0, self.intf, None, timeout=2000)
        except self.usb.core.USBError:
            pass
        for ep in (self.ep_in, self.ep_out):
            try:
                self.dev.clear_halt(ep)
            except self.usb.core.USBError:
                pass

    def xfer(self, cdb, data_out=None, n_in=0, timeout=5000):
        tag = self.tag
        self.tag = (self.tag + 1) & 0xFFFFFFFF
        length = len(data_out) if data_out is not None else n_in
        flags = 0x80 if n_in else 0x00
        cbw = struct.pack("<4sIIBBB", b"USBC", tag, length, flags, 0, len(cdb)) + bytes(cdb).ljust(16, b"\0")
        self.ep_out.write(cbw, timeout)
        got = b""
        if data_out is not None and len(data_out):
            self.ep_out.write(bytes(data_out), timeout)
        elif n_in:
            got = bytes(self.ep_in.read(n_in, timeout))
        csw = bytes(self.ep_in.read(13, timeout))
        sig, ctag, _, status = struct.unpack("<4sIIB", csw)
        if sig != b"USBS" or ctag != tag:
            raise Fail(f"bad status block ({csw.hex()})")
        if status != 0:
            raise Fail(f"command failed (status {status})")
        return got


def cdb_for(cmd, args=b""):
    return (struct.pack(">H", cmd) + bytes(args)).ljust(16, b"\xFF")


# ----------------------------------------------------------------- device ---
class Uboot:
    def __init__(self, bot):
        self.bot = bot

    def inquiry(self):
        r = self.bot.xfer(bytes([0x12, 0, 0, 0, 36, 0]), n_in=36)
        return r[8:16].decode(errors="replace").strip(), r[16:32].decode(errors="replace").strip()

    def cmd(self, cmd, args=b""):
        r = self.bot.xfer(cdb_for(cmd, args), n_in=16)
        if struct.unpack(">H", r[0:2])[0] != cmd:
            raise Fail(f"command {cmd:04X} answered as {r[0:2].hex()}")
        return r[2:]

    def write_block(self, cmd, addr, data):
        args = struct.pack(">IH", addr, len(data)) + b"\0" + struct.pack("<H", crc16(data))
        self.bot.xfer(cdb_for(cmd, args), data_out=data)

    def start_loader(self, blob):
        for off in range(0, len(blob), IO):                  # shipped already ciphered: send raw
            self.write_block(CMD_WRITE_MEMORY, LOADER_ADDR + off, blob[off:off + IO])
        self.cmd(CMD_JUMP, struct.pack(">IH", LOADER_ADDR, LOADER_ARG))

    def chip(self):
        p = self.cmd(CMD_READ_KEY, struct.pack(">I", 0x00AC6900))
        k = bytearray([p[5], p[4]])
        crc_cipher(k)
        key = k[0] | k[1] << 8
        p = self.cmd(CMD_GET_ONLINE_DEVICE)
        return key, p[0], struct.unpack_from("<I", p, 2)[0]

    def read(self, addr, n):
        out = bytearray()
        while len(out) < n:
            k = min(IO, n - len(out))
            out += self.bot.xfer(cdb_for(CMD_READ_FLASH, struct.pack(">IH", addr + len(out), k)), n_in=k)
        return bytes(out)

    def write_sector(self, addr, data):
        if addr < WRITE_MIN or addr >= APP_END or addr % SECTOR or len(data) != SECTOR:
            raise Fail(f"refusing to write {addr:#x}")
        self.cmd(CMD_ERASE_SECTOR, struct.pack(">I", addr))
        for off in range(0, SECTOR, IO):
            self.write_block(CMD_WRITE_FLASH, addr + off, data[off:off + IO])
        if self.read(addr, SECTOR) != data:
            raise Fail(f"sector {addr:#07x} did not verify")

    def run_app(self):
        try:
            self.cmd(CMD_RUN_APP, struct.pack(">I", 1))
        except Exception:
            pass                                             # it may reset before it answers


# ------------------------------------------------------------------- flow ---
def rescue(dev, image, loader, write, backup_dir, say=print, confirm=None):
    """Everything in one session: the FM-1 leaves UBOOT (and crashes again) as soon as it is let go."""
    vendor, product = dev.inquiry()
    say(f"  device: {vendor} {product}")
    if vendor != "WL82":
        raise Fail(f"not a WL82 UBOOT ({vendor!r})")
    dev.start_loader(loader)
    key, typ, fid = dev.chip()
    say(f"  chip key {key:04X}, flash type {typ}, id {fid:06X}")
    if (key, typ, fid) != (0x980F, 3, 0x856014):
        raise Fail("this is not the FM-1's chip and flash (expected key 980F, type 3, id 856014); nothing written")
    say("  reading the whole flash ...")
    t0 = time.time()
    now = dev.read(0, FLASH_SIZE)
    path = os.path.join(backup_dir, time.strftime("fm1-backup-%Y%m%d-%H%M%S.bin"))
    with open(path, "wb") as f:
        f.write(now)
    say(f"  backup saved: {path} ({time.time() - t0:.1f} s)")
    diff = [a for a in range(0, APP_END, SECTOR) if image[a:a + SECTOR] != now[a:a + SECTOR]]
    low = [a for a in diff if a < WRITE_MIN]
    if low:
        raise Fail("the protected head of the flash differs from V15 (sectors "
                   + " ".join(f"{a:#06x}" for a in low) + "): not writing; send this output and the backup")
    say(f"  {len(diff)} of {APP_END // SECTOR} firmware sectors differ from V15")
    if not write and confirm is not None:
        write = keep_alive(dev, confirm)
    if not write:
        say("  check passed. Nothing written: run again with --write to put V15 back.")
        return False
    # high to low: X0X's start-up code (low in the app area: its watchdog and its crash counter,
    # which bring it back to update mode) is the last thing replaced if the write is cut short
    for i, a in enumerate(reversed(diff)):
        for attempt in range(3):
            try:
                dev.write_sector(a, image[a:a + SECTOR])
                break
            except Fail as e:
                if attempt == 2:
                    raise Fail(f"{e}; the FM-1 is still in update mode: run the script again")
        say(f"\r  writing {i + 1}/{len(diff)}", end="")
    say("")
    say("  final read ...")
    expect = image + now[APP_END:]
    final = dev.read(0, FLASH_SIZE)
    if final != expect:
        bad = [a for a in range(0, FLASH_SIZE, SECTOR) if final[a:a + SECTOR] != expect[a:a + SECTOR]]
        raise Fail("final read differs in sectors " + " ".join(f"{a:#07x}" for a in bad)
                   + "; run the script again with --write")
    say("  flash now holds V15. Restarting the FM-1 ...")
    dev.run_app()
    return True


def keep_alive(dev, confirm):
    """Ask while the loader is kept busy (it resets the chip after ~3 s without a command)."""
    import threading
    stop, lost = threading.Event(), []

    def run():
        while not stop.wait(1.0):
            try:
                dev.cmd(CMD_GET_ONLINE_DEVICE)
            except Exception as e:
                lost.append(e)
                return
    t = threading.Thread(target=run, daemon=True)
    t.start()
    try:
        answer = confirm()
    finally:
        stop.set()
        t.join()
    if lost:
        raise Fail(f"the FM-1 dropped out while waiting ({lost[0]}); run it again")
    return answer


def get_loader(path):
    if path:
        blob = open(path, "rb").read()
    else:
        print("downloading JieLi's flash loader (wl82loader.bin) ...")
        with urllib.request.urlopen(LOADER_URL, timeout=30) as r:
            blob = r.read()
    if hashlib.sha256(blob).hexdigest() != LOADER_SHA256:
        raise Fail("wl82loader.bin: unexpected contents")
    return blob


def backend(usb):
    """libusb: pip's libusb-package (no Homebrew needed), else the system's or Homebrew's"""
    try:
        import libusb_package
        b = libusb_package.get_libusb1_backend()
        if b is not None:
            return b
    except ImportError:
        pass
    import usb.backend.libusb1 as lb
    for path in (None, "/opt/homebrew/lib/libusb-1.0.dylib", "/usr/local/lib/libusb-1.0.dylib"):
        b = lb.get_backend() if path is None else (lb.get_backend(find_library=lambda _: path)
                                                   if os.path.exists(path) else None)
        if b is not None:
            return b
    raise Fail("libusb not found: pip install libusb-package")


def open_device(usb, timeout):
    """Wait for 4C4A:8057 and take it from macOS's mass storage driver."""
    print("waiting for the FM-1 in update mode (switch it on, or wait for it to cycle) ...")
    be = backend(usb)
    t0 = time.time()
    while time.time() - t0 < timeout:
        dev = usb.core.find(idVendor=VID, idProduct=PID, backend=be)
        if dev is not None:
            print(f"found it after {time.time() - t0:.1f} s")
            try:
                try:
                    if dev.is_kernel_driver_active(0):
                        dev.detach_kernel_driver(0)
                except (NotImplementedError, usb.core.USBError) as e:
                    if getattr(e, "errno", None) not in (None, 2):
                        print(f"  (could not detach macOS's driver: {e})")
                bot = Bot(dev, usb)
                try:
                    Uboot(bot).inquiry()
                except Exception:
                    bot.reset_recovery()
                return bot
            except Exception as e:
                print(f"  could not open it ({e}); waiting for the next cycle")
                time.sleep(1.0)
                continue
        time.sleep(0.02)
    raise Fail("the FM-1 did not appear in update mode")


def ask():
    print("\n  Everything checks out, and the backup is saved.")
    try:
        return input("  Type yes and press Return to put the stock firmware back: ").strip().lower() == "yes"
    except EOFError:
        return False


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("package", help="M-VAVE's FM-1 V15 .fwsc")
    ap.add_argument("--write", action="store_true", help="write V15 (without it: check and back up only)")
    ap.add_argument("--ask", action="store_true", help="after the check and the backup, ask before writing")
    ap.add_argument("--loader", help="a local wl82loader.bin instead of downloading it")
    ap.add_argument("--wait", type=float, default=120, help="seconds to wait for the FM-1 (default 120)")
    ap.add_argument("--tries", type=int, default=5, help="attempts if it drops out mid-way (default 5)")
    args = ap.parse_args()
    try:
        raw = open(args.package, "rb").read()
        if hashlib.sha256(raw).hexdigest() != STOCK_SHA256:
            raise Fail(f"{args.package} is not M-VAVE's FM-1 V15 package (sha256 mismatch)")
        image = package_flash_image(raw)
        if len(image) != APP_END:
            raise Fail("unexpected flash entry size")
        loader = get_loader(args.loader)
        if os.geteuid() != 0:
            raise Fail("run it with sudo: macOS has to give the device up")
        try:
            import usb.core
            import usb.util
        except ImportError:
            raise Fail("pyusb is missing: ~/fm1-rescue/bin/pip install pyusb libusb-package")
        backup_dir = os.path.dirname(os.path.abspath(args.package))
        for attempt in range(1, args.tries + 1):
            bot = open_device(usb, args.wait)
            try:
                rescue(Uboot(bot), image, loader, args.write, backup_dir,
                       say=lambda *a, **k: print(*a, **k, flush=True),
                       confirm=ask if args.ask else None)
                return 0
            except (Fail, usb.core.USBError) as e:
                print(f"\n  attempt {attempt}: {e}")
                if isinstance(e, Fail) and "not writing" in str(e) or "not the FM-1" in str(e):
                    return 1
            finally:
                try:
                    usb.util.dispose_resources(bot.dev)
                except Exception:
                    pass
        raise Fail("gave up; send this whole output")
    except Fail as e:
        print(f"fm1_rescue: {e}")
        return 1


if __name__ == "__main__":
    sys.exit(main())

